import re

def extract_passengers(val):
    if pd.isna(val):
        return 0
    match = re.search(r'Occupants:\s*(\d+)', str(val))
    if match:
        return int(match.group(1))
    return 0

passengers = df['Onboard_Passengers'].apply(extract_passengers)
